"""Rules for the app proxy (IIS URL Rewrite), generated by the portal (REG-06, PRX-05, PRX-06).

The portal builds them from its application list (Administration > Proxy rules) and replaces only
the ``<rewrite><rules>`` block of the proxy's ``web.config``; every other setting there stays as
it is. Nobody writes proxy rules by hand.
"""

from __future__ import annotations

import re
# ElementTree reads only the proxy's own web.config, never input from a browser.
import xml.etree.ElementTree as ET  # nosec B405
from dataclasses import dataclass
from typing import Iterable
from xml.sax.saxutils import quoteattr  # nosec B406

SERVER_VARIABLES = ("HTTP_X_FORWARDED_PREFIX", "HTTP_X_FORWARDED_PROTO", "HTTP_X_FORWARDED_HOST",
                    "HTTP_X_FORWARDED_FOR")

_MODULE_PATH = re.compile(r"/[a-z][a-z0-9-]{1,30}")
_HOST = re.compile(r"[A-Za-z0-9][A-Za-z0-9.-]{0,252}")
_REWRITE = re.compile(r"<rewrite(?:\s[^>]*)?>(.*?)</rewrite>", re.S)
_RULES = re.compile(r"[ \t]*<rules(?:\s[^>]*)?>.*?</rules>|[ \t]*<rules\s*/>", re.S)
_WEB_SERVER_END = re.compile(r"([ \t]*)</system\.webServer>")


@dataclass(frozen=True)
class Upstream:
    """One app behind the proxy: ``path`` is ``/<app-id>`` for a module and ``/`` for the portal."""

    app_id: str
    path: str
    host: str
    port: int


def validate(upstreams: Iterable[Upstream]) -> list[str]:
    """Problems that would make the rules wrong: bad values, a path or host:port used twice."""
    problems: list[str] = []
    paths: dict[str, str] = {}
    targets: dict[tuple[str, int], str] = {}
    for upstream in upstreams:
        if upstream.path != "/" and not _MODULE_PATH.fullmatch(upstream.path):
            problems.append(f"{upstream.app_id}: path {upstream.path!r} is not /<app-id>")
        if not _HOST.fullmatch(upstream.host or ""):
            problems.append(f"{upstream.app_id}: host {upstream.host!r} is not a host name or address")
        if not isinstance(upstream.port, int) or not 1024 <= upstream.port <= 65535:
            problems.append(f"{upstream.app_id}: port must be a whole number 1024-65535")
        if upstream.path in paths:
            problems.append(f"{upstream.app_id}: path {upstream.path} already used by {paths[upstream.path]}")
        paths.setdefault(upstream.path, upstream.app_id)
        target = (upstream.host.lower(), upstream.port)
        if target in targets:
            problems.append(f"{upstream.app_id}: {upstream.host}:{upstream.port} already used by {targets[target]}")
        targets.setdefault(target, upstream.app_id)
    return problems


def _forwarding(prefix: str | None) -> list[str]:
    lines = ["    <serverVariables>"]
    if prefix:
        lines.append(f"      <set name=\"HTTP_X_FORWARDED_PREFIX\" value={quoteattr(prefix)} />")
    lines += [
        "      <set name=\"HTTP_X_FORWARDED_PROTO\" value=\"https\" />",
        "      <!-- The host the browser used; ARR passes 127.0.0.1 on to the app otherwise. -->",
        "      <set name=\"HTTP_X_FORWARDED_HOST\" value=\"{HTTP_HOST}\" />",
        "      <!-- Overwrite, never append: the client must not choose its own address (PRX-05). -->",
        "      <set name=\"HTTP_X_FORWARDED_FOR\" value=\"{REMOTE_ADDR}\" />",
        "    </serverVariables>",
    ]
    return lines


def iis_rules(upstreams: Iterable[Upstream], environment: str) -> str:
    """The complete ``<rules>`` element. Raises ``ValueError`` when ``validate`` finds problems."""
    upstreams = sorted(upstreams, key=lambda u: u.path)
    problems = validate(upstreams)
    if problems:
        raise ValueError("; ".join(problems))
    lines = [
        "<rules>",
        f"  <!-- Generated by the portal (Administration > Proxy rules) for environment {environment}. Do not edit here. -->",
        f"  <!-- Requires allowedServerVariables: {', '.join(SERVER_VARIABLES)} -->",
    ]
    core_rule: list[str] = []
    for upstream in upstreams:
        target = f"http://{upstream.host}:{upstream.port}/{{R:1}}"
        if upstream.path == "/":
            # Catch-all for the portal: must stay the last rule (PRX-06).
            core_rule = [
                f"  <rule name={quoteattr(upstream.app_id)} stopProcessing=\"true\">",
                "    <match url=\"^(.*)\" />",
                *_forwarding(None),
                f"    <action type=\"Rewrite\" url={quoteattr(target)} />",
                "  </rule>",
            ]
            continue
        segment = upstream.path.lstrip("/")
        lines += [
            f"  <rule name={quoteattr(upstream.app_id + '-slash')} stopProcessing=\"true\">",
            f"    <match url={quoteattr('^' + segment + '$')} />",
            f"    <action type=\"Redirect\" url={quoteattr(segment + '/')} redirectType=\"Permanent\" />",
            "  </rule>",
            f"  <rule name={quoteattr(upstream.app_id)} stopProcessing=\"true\">",
            f"    <match url={quoteattr('^' + segment + '/(.*)')} />",
            *_forwarding(upstream.path),
            f"    <action type=\"Rewrite\" url={quoteattr(target)} />",
            "  </rule>",
        ]
    lines += core_rule
    lines.append("</rules>")
    return "\n".join(lines) + "\n"


def current_rules(web_config: str) -> str | None:
    """The ``<rules>`` block of the ``<rewrite>`` section as it is now, without its indentation."""
    rewrite = _REWRITE.search(web_config)
    match = _RULES.search(web_config, rewrite.start(1), rewrite.end(1)) if rewrite else None
    if not match:
        return None
    lines = match.group(0).replace("\r\n", "\n").split("\n")
    indent = len(lines[0]) - len(lines[0].lstrip())
    return "\n".join(line[indent:] if not line[:indent].strip() else line.lstrip() for line in lines) + "\n"


def _indented(block: str, indent: str, newline: str) -> str:
    return newline.join((indent + line) if line else line for line in block.rstrip("\n").split("\n"))


def replace_rules(web_config: str, rules: str) -> str:
    """``web_config`` with its ``<rewrite><rules>`` block replaced by ``rules``; nothing else changes.

    Raises ``ValueError`` when the file has no ``<system.webServer>`` section or the result is not
    well-formed XML - the caller then leaves the file untouched.
    """
    newline = "\r\n" if "\r\n" in web_config else "\n"
    rewrite = _REWRITE.search(web_config)
    match = _RULES.search(web_config, rewrite.start(1), rewrite.end(1)) if rewrite else None
    if match:
        line = match.group(0).split("\n", 1)[0]
        indent = line[: len(line) - len(line.lstrip())]
        result = web_config[: match.start()] + _indented(rules, indent, newline) + web_config[match.end():]
    elif rewrite:
        opening = web_config.index(">", rewrite.start()) + 1
        line_start = web_config.rfind("\n", 0, rewrite.start()) + 1
        indent = web_config[line_start: rewrite.start()] + "  "
        result = web_config[:opening] + newline + _indented(rules, indent, newline) + web_config[opening:]
    else:
        end = _WEB_SERVER_END.search(web_config)
        if not end:
            raise ValueError("web.config has no <system.webServer> section")
        indent = end.group(1) + "  "
        block = f"{indent}<rewrite>{newline}{_indented(rules, indent + '  ', newline)}{newline}{indent}</rewrite>{newline}"
        result = web_config[: end.start()] + block + web_config[end.start():]
    try:
        ET.fromstring(result.lstrip("\ufeff"))  # nosec B314
    except ET.ParseError as exc:
        raise ValueError(f"web.config would not be well-formed XML: {exc}") from exc
    return result


def upstreams_in(web_config: str) -> dict[str, tuple[str, int]]:
    """``{app_id: (host, port)}`` of the rewrite rules in an existing ``web.config``.

    Lets the portal take over the upstreams of apps that were routed before it generated the rules.
    """
    rules = current_rules(web_config)
    if not rules:
        return {}
    found: dict[str, tuple[str, int]] = {}
    for rule in ET.fromstring(rules).iter("rule"):  # nosec B314
        action = rule.find("action")
        target = re.fullmatch(r"https?://([^/:]+):(\d+)/.*", (action.get("url") if action is not None else "") or "")
        if action is not None and action.get("type") == "Rewrite" and target:
            found[rule.get("name", "")] = (target.group(1), int(target.group(2)))
    return found
